package com.metaarch.catalog.category;
import java.net.URI; import java.util.*; import com.metaarch.catalog.common.PageResponse; import com.metaarch.catalog.product.*; import jakarta.validation.Valid; import org.springframework.data.domain.Pageable; import org.springframework.data.web.PageableDefault; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/categories") public class CategoryController {
 private final CategoryService service; private final ProductService products; private final com.metaarch.catalog.config.CatalogAccess access; public CategoryController(CategoryService s,ProductService p,com.metaarch.catalog.config.CatalogAccess access){service=s;products=p;this.access=access;}
 @org.springframework.security.access.prepost.PreAuthorize("hasAnyRole('ADMIN','GLOBAL_ADMIN','SUPER_ADMIN')") @PostMapping ResponseEntity<CategoryResponse> create(@Valid @RequestBody CategoryRequest r){CategoryResponse v=service.create(r);return ResponseEntity.created(URI.create("/api/v1/categories/"+v.id())).body(v);}
 @GetMapping List<CategoryResponse> list(){return service.list();} @GetMapping("/{id}") CategoryResponse get(@PathVariable UUID id){return service.get(id);} @org.springframework.security.access.prepost.PreAuthorize("hasAnyRole('ADMIN','GLOBAL_ADMIN','SUPER_ADMIN')") @PutMapping("/{id}") CategoryResponse update(@PathVariable UUID id,@Valid @RequestBody CategoryRequest r){return service.update(id,r);}
 @GetMapping("/{id}/products") PageResponse<ProductResponse> products(@PathVariable UUID id,@RequestParam(required=false) ProductStatus status,@RequestParam(required=false) String search,@RequestParam(required=false) String q,@RequestParam(required=false) String storeId,@PageableDefault(size=50,sort="name") Pageable pageable,Authentication authentication){service.get(id);String term=search!=null?search:q;if(authentication!=null&&authentication.getAuthorities().stream().anyMatch(a->"ROLE_LOCATION_ADMIN".equals(a.getAuthority())))return products.listForLocation(authentication,id,status,term,pageable);if(access.storeManager(authentication)){access.requireStore(authentication,storeId);return products.listForStore(storeId,id,status,term,pageable);}return products.list(id,status,term,null,pageable);}
 @org.springframework.security.access.prepost.PreAuthorize("hasAnyRole('ADMIN','GLOBAL_ADMIN','SUPER_ADMIN')") @DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) void delete(@PathVariable UUID id){service.delete(id);}
}
